1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.repository.OwnerRepository;
4	
5	/**
6	 * Shared city-membership logic. An owner belongs to the city named by their {@code city}
7	 * field, matched exactly, so every rule that reasons about a city's population (capacity,
8	 * per-city sequence) counts the same set of owners.
9	 */
10	final class Cities {
11	
12	    private Cities() {
13	    }
14	
15	    /**
16	     * The number of existing owners in the given city.
17	     */
18	    static long countIn(OwnerRepository ownerRepository, String city) {
19	        return ownerRepository.findAll().stream()
20	                .filter(existing -> city.equals(existing.getCity()))
21	                .count();
22	    }
23	}
