1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Comparator;
4	import java.util.Map;
5	import java.util.Optional;
6	import java.util.regex.Pattern;
7	
8	/**
9	 * Converts a raw telephone number to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a>
10	 * form: a leading '+' followed by 8 to 15 digits.
11	 *
12	 * <p>An explicit leading '+' and country code are kept; otherwise the default country code
13	 * {@code +61} is assumed and a single leading '0' is dropped from the national digits.
14	 * Spaces, dashes and brackets are stripped. So {@code "0412 345 678"} becomes
15	 * {@code "+61412345678"} and {@code "+64 21 123 456"} becomes {@code "+6421123456"}.
16	 */
17	public final class E164PhoneNumber {
18	
19	    /** Country code assumed when the input does not carry an explicit '+' prefix. */
20	    private static final String DEFAULT_COUNTRY_CODE = "61";
21	
22	    /** Separators removed before parsing: spaces, dashes and brackets. */
23	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
24	
25	    /** A well-formed E.164 number: '+' then 8 to 15 digits. */
26	    private static final Pattern E164 = Pattern.compile("\\+[0-9]{8,15}");
27	
28	    /**
29	     * Required national-number length (the digits after the country code) for the country
30	     * codes whose national number is a fixed length. Country codes not listed carry no
31	     * length rule here, so any national length within the generic E.164 bounds is accepted.
32	     */
33	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
34	            "1", 10,   // North American Numbering Plan
35	            "61", 9);  // Australia
36	
37	    private E164PhoneNumber() {
38	    }
39	
40	    /**
41	     * @param raw the caller-supplied telephone, in any common format
42	     * @return the E.164 string, or empty when {@code raw} cannot form a valid one
43	     */
44	    public static Optional<String> toE164(String raw) {
45	        if (raw == null) {
46	            return Optional.empty();
47	        }
48	        String trimmed = raw.trim();
49	        boolean explicitCountryCode = trimmed.startsWith("+");
50	        String cleaned = SEPARATORS.matcher(trimmed).replaceAll("");
51	        String digits;
52	        if (explicitCountryCode) {
53	            digits = cleaned.substring(1); // drop the '+', keep the country code
54	        }
55	        else {
56	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
57	            digits = DEFAULT_COUNTRY_CODE + national;
58	        }
59	        String candidate = "+" + digits;
60	        return E164.matcher(candidate).matches() ? Optional.of(candidate) : Optional.empty();
61	    }
62	
63	    /**
64	     * Checks a normalized E.164 number's national-number length against its country code.
65	     *
66	     * @param e164 a normalized E.164 number (a '+' followed by digits), as produced by
67	     *   {@link #toE164}
68	     * @return {@code true} when the national number has the length its country code
69	     *   requires, or the country code has no fixed-length rule; {@code false} when the
70	     *   length is wrong for a country code with a known requirement
71	     */
72	    public static boolean hasValidNationalNumberLength(String e164) {
73	        if (e164 == null || !e164.startsWith("+")) {
74	            return false;
75	        }
76	        String digits = e164.substring(1);
77	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
78	                .filter(entry -> digits.startsWith(entry.getKey()))
79	                .max(Comparator.comparingInt(entry -> entry.getKey().length()))
80	                .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
81	                .orElse(true);
82	    }
83	}
84

1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	
5	/**
6	 * Resolves an owner's locality (the canonical region). The postcode range is preferred
7	 * ({@link Postcodes#regionForPostcode(String)}); only when the postcode is absent or in
8	 * no known range does resolution fall back to a fixed city-to-region table:
9	 * Sydney->NSW, Melbourne->VIC, Brisbane->QLD.
10	 *
11	 * <p>Cities not in the table have no known region and resolve to {@code "UNKNOWN"}.
12	 */
13	public final class CityLocality {
14	
15	    /** City -> canonical region. Anything not listed resolves to {@link #UNKNOWN}. */
16	    private static final Map<String, String> CITY_REGION = Map.of(
17	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
18	
19	    /** The locality returned for a city with no known region. */
20	    public static final String UNKNOWN = "UNKNOWN";
21	
22	    private CityLocality() {
23	    }
24	
25	    /**
26	     * @param city the owner's city, as stored
27	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when it is
28	     *         not in the table (including a null city)
29	     */
30	    public static String forCity(String city) {
31	        return CITY_REGION.getOrDefault(city, UNKNOWN);
32	    }
33	
34	    /**
35	     * Resolves the locality preferring the postcode range, disambiguating cities that
36	     * share a name. Falls back to {@link #forCity(String)} when the postcode is absent
37	     * or in no known range.
38	     *
39	     * @param postcode the owner's postcode, as stored (may be null)
40	     * @param city     the owner's city, as stored
41	     * @return the region derived from the postcode, else from the city, else
42	     *         {@code "UNKNOWN"}
43	     */
44	    public static String forPostcodeOrCity(String postcode, String city) {
45	        String region = Postcodes.regionForPostcode(postcode);
46	        return region != null ? region : forCity(city);
47	    }
48	}
49

1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Postcode rules: the 4-digit format and the fixed per-region ranges (NSW 2000-2099,
8	 * VIC 3000-3099, QLD 4000-4099). Regions are resolved from a city by
9	 * {@link CityLocality}; this class only knows regions, so the two concerns stay
10	 * separate and reusable.
11	 *
12	 * <p>A region with no known range accepts any well-formed postcode.
13	 */
14	public final class Postcodes {
15	
16	    /** A postcode is exactly four decimal digits. */
17	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
18	
19	    /** Region -> inclusive 4-digit postcode range {low, high}. */
20	    private static final Map<String, int[]> REGION_RANGE = Map.of(
21	            "NSW", new int[] {2000, 2099},
22	            "VIC", new int[] {3000, 3099},
23	            "QLD", new int[] {4000, 4099});
24	
25	    private Postcodes() {
26	    }
27	
28	    /**
29	     * @param postcode the candidate postcode
30	     * @return {@code true} when {@code postcode} is exactly four digits
31	     */
32	    public static boolean hasValidFormat(String postcode) {
33	        return postcode != null && FOUR_DIGITS.matcher(postcode).matches();
34	    }
35	
36	    /**
37	     * Whether a well-formed postcode is acceptable for a region. A region with no known
38	     * range accepts any postcode. Callers must first confirm the format with
39	     * {@link #hasValidFormat(String)}.
40	     *
41	     * @param region   the canonical region, as resolved by {@link CityLocality}
42	     * @param postcode a 4-digit postcode
43	     * @return {@code true} when the region has no range, or the postcode falls within it
44	     */
45	    public static boolean isAllowedForRegion(String region, String postcode) {
46	        int[] range = REGION_RANGE.get(region);
47	        if (range == null) {
48	            return true;
49	        }
50	        int value = Integer.parseInt(postcode);
51	        return value >= range[0] && value <= range[1];
52	    }
53	
54	    /**
55	     * The canonical region whose range contains a postcode, the reverse of the
56	     * per-region ranges used by {@link #isAllowedForRegion(String, String)}.
57	     *
58	     * @param postcode the candidate postcode
59	     * @return the region containing {@code postcode}, or {@code null} when it is not
60	     *         well-formed or falls in no known range
61	     */
62	    public static String regionForPostcode(String postcode) {
63	        if (!hasValidFormat(postcode)) {
64	            return null;
65	        }
66	        int value = Integer.parseInt(postcode);
67	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
68	            int[] range = entry.getValue();
69	            if (value >= range[0] && value <= range[1]) {
70	                return entry.getKey();
71	            }
72	        }
73	        return null;
74	    }
75	}
