4	 * Computes the Luhn check digit over the digits contained in a string. Non-digit
5	 * characters are ignored, so the algorithm applies unchanged to formatted values such as
6	 * an owner's customer code ({@code PAR-FRA-0007}).
7	 *
8	 * <p>Walking right to left, every second digit (starting with the rightmost) is doubled,
9	 * casting out nines, and the check digit is the amount needed to bring the running total
10	 * to a multiple of ten.
11	 */
12	public final class LuhnCheckDigit {
13	
14	    private LuhnCheckDigit() {
15	    }
16	
17	    /**
18	     * @param value the string whose digits are checked (non-digits are ignored)
19	     * @return the Luhn check digit, {@code 0}-{@code 9}
20	     */
21	    public static int of(String value) {
22	        int sum = 0;
23	        boolean doubling = true;
24	        for (int i = value.length() - 1; i >= 0; i--) {
25	            char c = value.charAt(i);
26	            if (c < '0' || c > '9') {
27	                continue;
28	            }
29	            int digit = c - '0';
30	            if (doubling) {
31	                digit *= 2;
32	                if (digit > 9) {
33	                    digit -= 9;
34	                }
35	            }
36	            sum += digit;
37	            doubling = !doubling;
38	        }
39	        return (10 - (sum % 10)) % 10;
40	    }
41	}
